{
  "title": "functions.expression.InputValue",
  "description": "A concrete input value (post-compilation).\n\nRepresents any JSON-like value that can be passed to a Function,\nincluding rich content types (images, audio, video, files).",
  "anyOf": [
    {
      "title": "RichContentPart",
      "description": "Rich content (image, audio, video, file).",
      "$ref": "agent.completions.message.RichContentPart"
    },
    {
      "title": "Object",
      "description": "An object with string keys.",
      "type": "object",
      "additionalProperties": {
        "$ref": "functions.expression.InputValue"
      }
    },
    {
      "title": "Array",
      "description": "An array of values.",
      "type": "array",
      "items": {
        "$ref": "functions.expression.InputValue"
      }
    },
    {
      "title": "String",
      "description": "A string value.",
      "type": "string"
    },
    {
      "title": "Integer",
      "description": "An integer value.",
      "type": "integer",
      "minimum": -9223372036854775808,
      "maximum": 9223372036854775807
    },
    {
      "title": "Number",
      "description": "A floating-point number.",
      "type": "number",
      "minimum": -3.4028234663852886e+38,
      "maximum": 3.4028234663852886e+38
    },
    {
      "title": "Boolean",
      "description": "A boolean value.",
      "type": "boolean"
    }
  ]
}

{
  "title": "functions.expression.Special",
  "description": "Predefined expression behaviors that require no user-authored code.",
  "anyOf": [
    {
      "title": "Input",
      "description": "Returns the params input as-is.",
      "type": "string",
      "enum": [
        "input"
      ]
    },
    {
      "title": "Output",
      "description": "Returns the params output as-is.",
      "type": "string",
      "enum": [
        "output"
      ]
    },
    {
      "title": "TaskOutputL1Normalized",
      "description": "L1-normalizes the output. Scalar/Err pass through.\nVector: L1 normalize. Vectors: L1 normalize each.",
      "type": "string",
      "enum": [
        "task_output_l1_normalized"
      ]
    },
    {
      "title": "TaskOutputWeightedSum",
      "description": "Weighted sum of the output. Vector → Scalar. Vectors → Vector.",
      "type": "string",
      "enum": [
        "task_output_weighted_sum"
      ]
    },
    {
      "title": "InputItemsOutputLength",
      "description": "Returns the length of input['items'] as u64",
      "type": "string",
      "enum": [
        "input_items_output_length"
      ]
    },
    {
      "title": "InputItemsOptionalContextSplit",
      "description": "Splits an input containing items and optionally context into multiple inputs",
      "type": "string",
      "enum": [
        "input_items_optional_context_split"
      ]
    },
    {
      "title": "InputItemsOptionalContextMerge",
      "description": "Merges multiple inputs containing items and optionally context into a single input",
      "type": "string",
      "enum": [
        "input_items_optional_context_merge"
      ]
    }
  ]
}

{
  "title": "functions.expression.BooleanInputSchema",
  "description": "Schema for a boolean input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the boolean.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.BooleanInputSchemaType"
    }
  }
}

{
  "title": "agent.completions.message.AssistantToolCallFunctionExpression",
  "description": "Expression variant of [`AssistantToolCallFunction`] for dynamic content.",
  "type": "object",
  "properties": {
    "arguments": {
      "description": "The arguments expression.

A value that can be either a literal or an expression.

This allows Function definitions to mix static values with dynamic
expressions. During compilation, expressions are evaluated while
literal values pass through unchanged.

# Example

Literal value:
```json
"hello world"
```

JMESPath expression:
```json
{"$jmespath": "input.greeting"}
```

Starlark expression:
```json
{"$starlark": "input['greeting']"}
```",
      "anyOf": [
        {
          "title": "Expression",
          "description": "An expression (JMESPath or Starlark) to evaluate.",
          "$ref": "functions.expression.Expression"
        },
        {
          "title": "Value",
          "description": "A literal value.",
          "type": "string"
        }
      ]
    },
    "name": {
      "description": "The function name expression.

A value that can be either a literal or an expression.

This allows Function definitions to mix static values with dynamic
expressions. During compilation, expressions are evaluated while
literal values pass through unchanged.

# Example

Literal value:
```json
"hello world"
```

JMESPath expression:
```json
{"$jmespath": "input.greeting"}
```

Starlark expression:
```json
{"$starlark": "input['greeting']"}
```",
      "anyOf": [
        {
          "title": "Expression",
          "description": "An expression (JMESPath or Starlark) to evaluate.",
          "$ref": "functions.expression.Expression"
        },
        {
          "title": "Value",
          "description": "A literal value.",
          "type": "string"
        }
      ]
    }
  }
}

{
  "title": "agent.completions.message.MessageExpression",
  "description": "A message with expressions for dynamic content.\n\nThis is the expression variant of [`Message`] used in function definitions\nwhere message content can be computed from the function input at runtime.\nSupports both JMESPath and Starlark expressions.",
  "anyOf": [
    {
      "title": "Developer",
      "type": "object",
      "$ref": "agent.completions.message.DeveloperMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "developer"
          ]
        }
      }
    },
    {
      "title": "System",
      "type": "object",
      "$ref": "agent.completions.message.SystemMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "system"
          ]
        }
      }
    },
    {
      "title": "User",
      "type": "object",
      "$ref": "agent.completions.message.UserMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "user"
          ]
        }
      }
    },
    {
      "title": "Assistant",
      "type": "object",
      "$ref": "agent.completions.message.AssistantMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "assistant"
          ]
        }
      }
    },
    {
      "title": "Tool",
      "type": "object",
      "$ref": "agent.completions.message.ToolMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "tool"
          ]
        }
      }
    }
  ]
}

